# dependencies = []
# ///
# MISE description="Make sure that the Docker server is reachable"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

if not helpers.has_tool("docker"):
  helpers.print_error("The 'docker' command-line tool is not installed.")
  sys.exit(1)

if helpers.tool("docker", "info", stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode != 0:
  helpers.print_error("Cannot connect to the Docker server.")
  helpers.print_yellow("Start the Docker daemon, or correct DOCKER_HOST.")
  sys.exit(1)
